import React, { useState, useEffect } from 'react';
import { Route, Routes, Link, useNavigate } from 'react-router-dom';
import ResortList from './components/ResortList'; // Adjust import path as needed
import ResortDetails from './components/ResortDetails'; // Adjust import path as needed
import Register from './components/Register'; // Adjust import path as needed
import Login from './components/Login'; // Adjust import path as needed
import { fetchResorts, fetchResort } from './api'; // Adjust import path as needed
import { useAuth } from './components/AuthProvider'; // Ensure correct path to AuthProvider

function App() {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');
  const { auth, logout } = useAuth(); // Destructure auth state and functions
  const navigate = useNavigate();

  useEffect(() => {
    // Redirect to login if not authenticated
    if (!auth) {
      navigate('/login');
    }
  }, [auth, navigate]);

  useEffect(() => {
    const loadResorts = async () => {
      try {
        const data = await fetchResorts();
        if (Array.isArray(data)) {
          setResorts(data);
        } else {
          console.error('Unexpected data format:', data);
        }
      } catch (error) {
        console.error('Error loading resorts:', error);
      }
    };

    if (auth) {
      loadResorts();
    }
  }, [auth]);

  const handleSearch = async () => {
    try {
      const resortData = await fetchResort(search);
      if (resortData) {
        setResorts([resortData]);
      } else {
        console.error('No data found for the given search term');
      }
    } catch (error) {
      console.error('Error searching for resort:', error);
    }
  };

  return (
    <div>
      <nav>
        <ul>
          {auth ? (
            <>
              <li>
                <Link to="/">Home</Link>
              </li>
              <li>
                <button onClick={() => { logout(); navigate('/login'); }}>Logout</button>
              </li>
            </>
          ) : (
            <>
              <li>
                <Link to="/register">Register</Link>
              </li>
              <li>
                <Link to="/login">Login</Link>
              </li>
            </>
          )}
        </ul>
      </nav>

      <Routes>
        <Route
          path="/"
          element={
            auth ? (
              <div>
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search for resorts"
                />
                <button onClick={handleSearch}>Search</button>
                <ResortList resorts={resorts} />
              </div>
            ) : (
              <div>Please log in to view resorts.</div>
            )
          }
        />
        <Route path="/register" element={<Register />} />
        <Route path="/login" element={<Login />} />
        <Route path="/resort/:slug" element={<ResortDetails />} />
      </Routes>
    </div>
  );
}

export default App;
